package com.iiop.maintenance.support;
import cn.dev33.satoken.exception.*;import com.iiop.common.api.*;import com.iiop.common.constant.HeaderConstants;import com.iiop.common.exception.BizException;import com.iiop.common.trace.TraceContext;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.util.UUID;import org.slf4j.*;import org.springframework.dao.DuplicateKeyException;import org.springframework.http.*;import org.springframework.stereotype.Component;import org.springframework.web.bind.annotation.*;import org.springframework.web.filter.OncePerRequestFilter;
public final class MaintenanceSupport {private MaintenanceSupport(){}
 @Component public static class TraceFilter extends OncePerRequestFilter{@Override protected void doFilterInternal(HttpServletRequest q,HttpServletResponse s,FilterChain c)throws java.io.IOException,ServletException{String id=q.getHeader(HeaderConstants.REQUEST_ID);if(id==null||id.isBlank())id=UUID.randomUUID().toString();TraceContext.setTraceId(id);s.setHeader(HeaderConstants.REQUEST_ID,id);s.setHeader(HeaderConstants.TRACE_ID,id);try{c.doFilter(q,s);}finally{TraceContext.clear();}}}
 @RestControllerAdvice public static class Errors{private static final Logger log=LoggerFactory.getLogger(Errors.class);@ExceptionHandler(BizException.class)ResponseEntity<Result<Void>>biz(BizException e){return ResponseEntity.status(status(e.getErrorCode())).body(Result.failure(e.getErrorCode(),e.getMessage()));}@ExceptionHandler(NotLoginException.class)ResponseEntity<Result<Void>>login(){return ResponseEntity.status(401).body(Result.failure(ErrorCode.UNAUTHORIZED,ErrorCode.UNAUTHORIZED.getMessage()));}@ExceptionHandler(NotPermissionException.class)ResponseEntity<Result<Void>>permission(){return ResponseEntity.status(403).body(Result.failure(ErrorCode.FORBIDDEN,ErrorCode.FORBIDDEN.getMessage()));}@ExceptionHandler(DuplicateKeyException.class)ResponseEntity<Result<Void>>duplicate(){return ResponseEntity.status(409).body(Result.failure(ErrorCode.CONFLICT,"数据已存在"));}@ExceptionHandler(Exception.class)ResponseEntity<Result<Void>>other(Exception e){log.error("维修服务未处理异常",e);return ResponseEntity.internalServerError().body(Result.failure(ErrorCode.INTERNAL_ERROR,ErrorCode.INTERNAL_ERROR.getMessage()));}private HttpStatus status(ErrorCode c){return switch(c){case NOT_FOUND->HttpStatus.NOT_FOUND;case CONFLICT->HttpStatus.CONFLICT;case SERVICE_UNAVAILABLE->HttpStatus.SERVICE_UNAVAILABLE;case FORBIDDEN->HttpStatus.FORBIDDEN;case UNAUTHORIZED->HttpStatus.UNAUTHORIZED;default->HttpStatus.BAD_REQUEST;};}}
}
